func (h *ExecuteHealHandler) fetchAndWriteChunked(ctx context.Context, entry *source.TableRegistry, ids []string, label string) int {
	totalWritten := 0
	for start := 0; start < len(ids); start += segAChunkSize {
		end := start + segAChunkSize
		if end > len(ids) {
			end = len(ids)
		}

		written, err := h.FetchAndWriteByIDs(ctx, entry, ids[start:end])
		if err != nil {
			observability.Ctx(ctx, h.logger).Error("[execute-heal-a] chunk heal failed", zap.String("label", label), zap.Int("chunk_start", start), zap.Int("chunk_size", end-start), zap.Error(err))
		}
		totalWritten += written
		if start > 0 {
			observability.Ctx(ctx, h.logger).Info("[execute-heal-a] chunk progress", zap.String("label", label), zap.Int("written_so_far", totalWritten), zap.Int("total_ids", len(ids)))
		}
	}
	return totalWritten
}

